import { CatalystNoSQLError } from '../utils/error';
import { NoSQLByte } from './byte';
import { DataType } from './enum';
import { NoSQLByteSet, NoSQLNumberSet, NoSQLStringSet } from './set';
export class NoSQLMarshall {
    static makeNull() {
        return {
            [DataType.NULL]: true
        };
    }
    static makeString(value) {
        return {
            [DataType.S]: value
        };
    }
    static makeNumber(value) {
        if ([Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]
            .map((val) => val.toString())
            .includes(value.toString())) {
            throw new CatalystNoSQLError('invalid_number', `Invalid number value ${value.toString()}`);
        }
        else if (value > Number.MAX_SAFE_INTEGER) {
            throw new CatalystNoSQLError('unsafe_number', `Number ${value.toString()} is greater than Number.MAX_SAFE_INTEGER. Use BigInt`);
        }
        else if (value < Number.MIN_SAFE_INTEGER) {
            throw new CatalystNoSQLError('unsafe_number', `Number ${value.toString()} is lesser than Number.MIN_SAFE_INTEGER. Use BigInt`);
        }
        return { N: value.toString() };
    }
    static makeByte(value) {
        return {
            [DataType.B]: value instanceof NoSQLByte ? value : new NoSQLByte(value)
        };
    }
    static makeBoolean(value) {
        return {
            [DataType.BOOL]: value === true ? 'true' : 'false'
        };
    }
    static makeList(value) {
        return {
            [DataType.L]: value.map((val) => {
                return this.make(val);
            })
        };
    }
    static makeMap(value, options) {
        const map = {};
        if (value instanceof Map) {
            for (const [key, val] of value) {
                if (typeof val !== 'function' &&
                    (value !== undefined || !options?.removeUndefinedValues)) {
                    map[key] = this.make(val, options);
                }
            }
        }
        Object.entries(value).forEach(([key, val]) => {
            if (typeof val !== 'function' &&
                (value !== undefined || !options?.removeUndefinedValues)) {
                map[key] = this.make(val, options);
            }
        });
        return {
            [DataType.M]: map
        };
    }
    static makeStringSet(value) {
        return {
            [DataType.SS]: value instanceof NoSQLStringSet ? value : new NoSQLStringSet([...value])
        };
    }
    static makeNumberSet(value) {
        return {
            [DataType.SN]: value instanceof NoSQLNumberSet ? value : new NoSQLNumberSet([...value])
        };
    }
    static makeByteSet(value) {
        return {
            [DataType.SB]: value instanceof NoSQLByteSet ? value : new NoSQLByteSet([...value])
        };
    }
    static makeSet(set, options) {
        const setToOperate = options?.removeUndefinedValues
            ? new Set([...set].filter((value) => value !== undefined))
            : set;
        if (!options?.removeUndefinedValues && setToOperate.has(undefined)) {
            throw new Error('Set cannot contain "undefined" value. Pass options.removeUndefinedValues=true to remove undefined values from map/list/set.');
        }
        if (setToOperate.size === 0) {
            if (options?.convertEmptyValues) {
                return this.makeNull();
            }
            throw new Error('Pass a non-empty set, or options.convertEmptyValues=true.');
        }
        const item = setToOperate.values().next().value;
        if (typeof item === 'number' || typeof item === 'bigint') {
            return this.makeNumberSet(set);
        }
        else if (typeof item === 'string') {
            return this.makeStringSet(set);
        }
        else if (NoSQLByte.isBuffer(item)) {
            return this.makeByteSet(set);
        }
        else {
            throw new Error(`Only Number Set (SN), Binary Set (SB) or String Set (SS) are allowed.`);
        }
    }
    static make(data, options) {
        if (data === undefined) {
            throw new Error(`Pass options.removeUndefinedValues=true to remove undefined values from map/array/set.`);
        }
        else if (data === null && typeof data === 'object') {
            return this.makeNull();
        }
        else if (Array.isArray(data)) {
            return this.makeList(data);
        }
        else if (data instanceof Set) {
            return this.makeSet(data, options);
        }
        else if (data?.constructor?.name === 'Map') {
            return this.makeMap(data, options);
        }
        else if (data?.constructor?.name === 'Object' ||
            (!data.constructor && typeof data === 'object')) {
            return this.makeMap(data, options);
        }
        else if (NoSQLByte.isBuffer(data)) {
            if (data.length === 0 && options?.convertEmptyValues) {
                return this.makeNull();
            }
            return this.makeByte(data);
        }
        else if (typeof data === 'boolean') {
            return this.makeBoolean(data);
        }
        else if (typeof data === 'number') {
            return this.makeNumber(data);
        }
        else if (typeof data === 'bigint') {
            return this.makeNumber(data);
        }
        else if (typeof data === 'string') {
            if (data.length === 0 && options?.convertEmptyValues) {
                return this.makeNull();
            }
            return this.makeString(data);
        }
        else if (options?.convertClassInstanceToMap && typeof data === 'object') {
            return this.makeMap(data, options);
        }
        throw new Error(`Unsupported type passed. Pass options.convertClassInstanceToMap=true to marshall typeof object as map attribute.`);
    }
}
